import{_ as r,C as s,o as d,c as o,j as t,E as e,a as l,a3 as n}from"./chunks/framework.C6R8kWFE.js";const q=JSON.parse(`{"title":"4-hafta (Mentor)","description":"","frontmatter":{"title":"4-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"n":4,"bob":"II-bob · Zamonaviy IT yo‘nalishlari va raqamli infratuzilma asoslari","lessons":[{"g":10,"title":"Internet qanday ishlaydi? IP, hosting, domen, DNS, brauzer, HTTP/HTTPS","lead":"Siz brauzerga manzil yozasiz va bir soniyada sahifa ochiladi. Bu orada IP, DNS, hosting va HTTPS qanday ishlaydi? Bugun internetning «ichki dunyosi»ga kiramiz.","link":"/mentor/8-sinf-cs/hafta-04/dars-1","slide":"/slaydlar/8-sinf-cs/hafta-04/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-04/dars-1-test.html"},{"g":11,"title":"Bulutli xizmatlar va onlayn hamkorlik vositalari (1-qism): bulutli saqlash, yuklash va ulashish","lead":"Telefoningiz yo'qolsa, undagi rasmlar ham yo'qoladimi? Agar ular «bulutda» bo'lsa — yo'q. Bugun bulut nima ekanini, fayllarni qanday yuklash va kimga qanday ruxsat bilan ulashishni o'rganamiz.","link":"/mentor/8-sinf-cs/hafta-04/dars-2","slide":"/slaydlar/8-sinf-cs/hafta-04/dars-2.html","test":"/slaydlar/8-sinf-cs/hafta-04/dars-2-test.html"},{"g":12,"title":"Bulutli xizmatlar va onlayn hamkorlik vositalari (2-qism): onlayn hujjatlar va vazifalarni boshqarish","lead":"To'rt kishi bitta taqdimotni qanday birga tayyorlaydi? Faylni bir-biriga 10 marta yuborib emas! Bugun bitta onlayn hujjatda birga yozamiz, izoh qoldiramiz va Trello doskasida vazifalarni bo'lishamiz.","link":"/mentor/8-sinf-cs/hafta-04/dars-3","slide":"/slaydlar/8-sinf-cs/hafta-04/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-04/dars-3-test.html"}],"test":"/slaydlar/8-sinf-cs/hafta-04/hafta-test.html"}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-04/index.md","filePath":"mentor/8-sinf-cs/hafta-04/index.md"}`),h={name:"mentor/8-sinf-cs/hafta-04/index.md"},u={class:"blk"},y={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},g={class:"blk"},c={id:"baholash-mezoni",tabindex:"-1"};function m(x,a,b,k,v,z){const i=s("Icon");return d(),o("div",null,[t("div",u,[t("h2",y,[e(i,{name:"house"}),a[0]||(a[0]=l(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=t("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=n('<p>Har bir vazifa 20–30 daqiqa vaqt oladi. Vazifalar daftarda yoki kompyuterda alohida papkada saqlanadi. Akkaunt kerak bo&#39;lgan qadamlarni ota-onangiz ruxsati va yordami bilan bajaring; akkaunt bo&#39;lmasa, shu qadamni daftarda chizma yoki jadval ko&#39;rinishida bajaring.</p><h2 id="_10-dars-uchun-internet-qanday-ishlaydi" tabindex="-1">10-dars uchun (Internet qanday ishlaydi?) <a class="header-anchor" href="#_10-dars-uchun-internet-qanday-ishlaydi" aria-label="Permalink to &quot;10-dars uchun (Internet qanday ishlaydi?)&quot;">​</a></h2><p><strong>1-topshiriq: «Internet yo&#39;li» mini-loyihasi</strong></p><ol><li>Sevimli saytingizni tanlang va uning to&#39;liq havolasini daftarga yozing.</li><li>Havolani bo&#39;laklarga ajrating: protokol, subdomen (bo&#39;lsa), domen nomi, zona, yo&#39;l.</li><li>Manzil <code>https://</code> bilan boshlanishini va qulf belgisi borligini tekshiring.</li><li>Sahifa ochilishining 5 bosqichini (siz → DNS → server → javob → brauzer) o&#39;z so&#39;zingiz bilan 5 jumlada yozing.</li></ol><p><strong>Kutiladigan natija:</strong> havolaning to&#39;g&#39;ri tahlili, HTTPS bo&#39;yicha xulosa va 5 bosqichli tushuntirish.</p><h2 id="_11-dars-uchun-bulutli-xizmatlar-1-qism" tabindex="-1">11-dars uchun (Bulutli xizmatlar, 1-qism) <a class="header-anchor" href="#_11-dars-uchun-bulutli-xizmatlar-1-qism" aria-label="Permalink to &quot;11-dars uchun (Bulutli xizmatlar, 1-qism)&quot;">​</a></h2><p><strong>2-topshiriq: «Mening bulutim»</strong></p><ol><li>Google Drive yoki OneDrive da (yoki daftarda daraxt ko&#39;rinishida) maktab fanlari bo&#39;yicha papka tuzilmasini yarating: kamida 3 ta fan papkasi, ulardan birida <code>4-hafta</code> ichki papkasi.</li><li>2 ta faylni (konspekt surati, referat yoki rasm) ma&#39;noli nom bilan joylang: <code>Fan_Mavzu_Familiya</code>.</li><li>Fayllardan birini ota-onangizga <strong>Ko&#39;ruvchi</strong> ruxsati bilan ulashing. Ruxsat sozlamasini ekran rasmiga oling yoki daftarga yozing.</li><li>3 jumla yozing: nega aynan shu ruxsatni tanladingiz va qaysi fayllarni hech qachon ochiq havola bilan ulashmaysiz.</li></ol><p><strong>Kutiladigan natija:</strong> tartibli papka tuzilmasi, to&#39;g&#39;ri nomlangan fayllar va asoslangan ruxsat tanlovi.</p><h2 id="_12-dars-uchun-bulutli-xizmatlar-2-qism" tabindex="-1">12-dars uchun (Bulutli xizmatlar, 2-qism) <a class="header-anchor" href="#_12-dars-uchun-bulutli-xizmatlar-2-qism" aria-label="Permalink to &quot;12-dars uchun (Bulutli xizmatlar, 2-qism)&quot;">​</a></h2><p><strong>3-topshiriq: «Oilaviy reja»</strong></p><ol><li>Trello da (yoki qog&#39;ozda 3 ustun chizib) «Dam olish kuni» doskasini yarating: <strong>Qilinadi</strong>, <strong>Jarayonda</strong>, <strong>Bajarildi</strong>.</li><li>Kamida 5 ta karta qo&#39;shing (masalan: xarid, tozalash, sayr, uy vazifasi, mehmon kutish), har biriga mas&#39;ul oila a&#39;zosi va muddat yozing.</li><li>Kun davomida kamida 3 ta kartani «Bajarildi» ustuniga o&#39;tkazing.</li><li>Google Docs (yoki Word onlayn) da 5 jumlali hisobot yozing: nima rejalashtirildi, nima bajarildi, nima qiyin bo&#39;ldi. Bitta oila a&#39;zosini <strong>Izohlovchi</strong> qilib qo&#39;shing va uning izohiga javob yozing.</li></ol><p><strong>Kutiladigan natija:</strong> 3 ustunli doska (kamida 5 karta), hisobot va kamida 1 ta izoh-javob.</p><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><p>Dars boshida 2-topshiriq bo&#39;yicha 2–3 o&#39;quvchining ruxsat tanlovini muhokama qiling (nega Ko&#39;ruvchi, nega Muharrir emas). 3-topshiriqdagi doskalarni sinfda qisqa ko&#39;rsatish (5 daqiqa) 13-dars (bulutli xizmatlar, 3-qism) va keyingi Git va GitHub mavzusiga ko&#39;prik bo&#39;ladi: «versiya tarixi» va «jamoaviy ish» g&#39;oyalarini eslating.</p>',15))]),t("div",g,[t("h2",c,[e(i,{name:"list-checks"}),a[3]||(a[3]=l(" Baholash mezoni ",-1)),a[4]||(a[4]=t("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=n('<p>Dasturdagi mezonlarga asoslangan (100 ballik shkala): <strong>90–100 — 5</strong>, <strong>71–89 — 4</strong>, <strong>60–70 — 3</strong>, <strong>0–59 — 2</strong>.</p><p>Dasturda joriy nazorat (amaliy mashg&#39;ulotlar, darsdagi faollik, tezkor savol-javoblar va uy vazifasi) o&#39;quv jarayoni davomida o&#39;tkaziladi. Quyida 4-haftaning 3 ta darsi bo&#39;yicha har bir o&#39;quvchi ishtirokini qayd etish uchun baholash jadvali keltirilgan.</p><h2 id="mezonlar-har-bir-dars-uchun" tabindex="-1">Mezonlar (har bir dars uchun) <a class="header-anchor" href="#mezonlar-har-bir-dars-uchun" aria-label="Permalink to &quot;Mezonlar (har bir dars uchun)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th style="text-align:center;">Max ball</th><th>Tavsif</th></tr></thead><tbody><tr><td>Nazariya va tushunchalar</td><td style="text-align:center;">30</td><td>IP, domen, hosting, DNS, HTTP/HTTPS; bulut tushunchasi, xizmatlar, ruxsat darajalari; onlayn hujjat va vazifa vositalari</td></tr><tr><td>Amaliy ko&#39;nikmalar</td><td style="text-align:center;">30</td><td>Havolani tahlil qilish, HTTPS tekshiruvi; faylni yuklash va ulashish; birgalikda tahrir, izoh, versiya tarixi, Trello doskasi</td></tr><tr><td>Xavfsizlik va hamkorlik</td><td style="text-align:center;">20</td><td>Parolni faqat to&#39;g&#39;ri HTTPS saytda kiritish, eng kam ruxsat qoidasi, akkauntdan chiqish, guruhda hurmatli muloqot</td></tr><tr><td>Uyga vazifa</td><td style="text-align:center;">20</td><td>Uy vazifasi to&#39;liq, sifatli va vaqtida bajarilgan</td></tr><tr><td><strong>Jami</strong></td><td style="text-align:center;"><strong>100</strong></td><td></td></tr></tbody></table><hr><h2 id="_10-dars-internet-qanday-ishlaydi-ip-hosting-domen-dns-brauzer-http-https" tabindex="-1">10-dars (Internet qanday ishlaydi? IP, hosting, domen, DNS, brauzer, HTTP/HTTPS) <a class="header-anchor" href="#_10-dars-internet-qanday-ishlaydi-ip-hosting-domen-dns-brauzer-http-https" aria-label="Permalink to &quot;10-dars (Internet qanday ishlaydi? IP, hosting, domen, DNS, brauzer, HTTP/HTTPS)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">Nazariya /30</th><th style="text-align:center;">Amaliyot /30</th><th style="text-align:center;">Xavfsizlik /20</th><th style="text-align:center;">Uy vazifasi /20</th><th style="text-align:center;">Jami</th><th style="text-align:center;">Baho</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><hr><h2 id="_11-dars-bulutli-xizmatlar-1-qism-saqlash-yuklash-va-ulashish" tabindex="-1">11-dars (Bulutli xizmatlar, 1-qism: saqlash, yuklash va ulashish) <a class="header-anchor" href="#_11-dars-bulutli-xizmatlar-1-qism-saqlash-yuklash-va-ulashish" aria-label="Permalink to &quot;11-dars (Bulutli xizmatlar, 1-qism: saqlash, yuklash va ulashish)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">Nazariya /30</th><th style="text-align:center;">Amaliyot /30</th><th style="text-align:center;">Xavfsizlik /20</th><th style="text-align:center;">Uy vazifasi /20</th><th style="text-align:center;">Jami</th><th style="text-align:center;">Baho</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><hr><h2 id="_12-dars-bulutli-xizmatlar-2-qism-onlayn-hujjatlar-va-vazifalarni-boshqarish" tabindex="-1">12-dars (Bulutli xizmatlar, 2-qism: onlayn hujjatlar va vazifalarni boshqarish) <a class="header-anchor" href="#_12-dars-bulutli-xizmatlar-2-qism-onlayn-hujjatlar-va-vazifalarni-boshqarish" aria-label="Permalink to &quot;12-dars (Bulutli xizmatlar, 2-qism: onlayn hujjatlar va vazifalarni boshqarish)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">Nazariya /30</th><th style="text-align:center;">Amaliyot /30</th><th style="text-align:center;">Hamkorlik /20</th><th style="text-align:center;">Uy vazifasi /20</th><th style="text-align:center;">Jami</th><th style="text-align:center;">Baho</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><p>Guruhli ishda (12-dars) «Hamkorlik» mezoni bo&#39;yicha kuzating: o&#39;quvchi o&#39;z bo&#39;limini yozdimi, jamoadoshiga izoh qoldirdimi, Trello kartasidagi vazifani muddatida bajardimi.</p><hr><h2 id="_4-hafta-yakuni" tabindex="-1">4-hafta yakuni <a class="header-anchor" href="#_4-hafta-yakuni" aria-label="Permalink to &quot;4-hafta yakuni&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">10-dars</th><th style="text-align:center;">11-dars</th><th style="text-align:center;">12-dars</th><th style="text-align:center;">O&#39;rtacha ball</th><th style="text-align:center;">Yakuniy baho</th><th>Izoh va tavsiyalar</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr></tbody></table><hr><h2 id="hafta-xulosasi-va-keyingi-darslarga-ko-prik" tabindex="-1">Hafta xulosasi va keyingi darslarga ko&#39;prik <a class="header-anchor" href="#hafta-xulosasi-va-keyingi-darslarga-ko-prik" aria-label="Permalink to &quot;Hafta xulosasi va keyingi darslarga ko&#39;prik&quot;">​</a></h2><p>O&#39;quvchilar internetning texnik asoslarini (IP, domen, DNS, hosting, HTTPS) va undan foydalanadigan bulutli xizmatlarni o&#39;zlashtirdilar: fayllarni bulutda saqlash, xavfsiz ulashish, onlayn hujjatlarda birga ishlash va vazifalarni Trello da boshqarish. Keyingi 5-haftada bulutli xizmatlar mavzusi 13-darsda yakunlanadi, so&#39;ng Git va GitHub — dasturchilarning bulutdagi hamkorlik vositasi — bilan tanishamiz: repository, commit va versiya nazorati tushunchasi bugungi «versiya tarixi» g&#39;oyasining davomidir.</p>',20))])])}const p=r(h,[["render",m]]);export{q as __pageData,p as default};
